mask=np.array([[1,1,0,1],[1,1,1,0]],dtype=int)
def transforms(a):
  arr=[]
  for k in range(4):
    b=np.rot90(a,k)
    for c in (b,np.fliplr(b)):
      if not any(np.array_equal(c,x) for x in arr): arr.append(c)
  return arr
